head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > removeHoliday]<br/>setHoliday() 메소드로 설정된 휴일 정보를 모두 제거합니다.",
    "validation" : [
        "removeHoliday() 메소드 호출 시 setHoliday() 메소드로 설정된 휴일 정보를 모두 제거합니다.",
        "setHolidayRef() 메소드로 설정된 휴일 정보는 제거되지 않습니다.",
        "setHoliday() 메소드로 적용된 'w2calendar_holiday' CSS 클래스를 제거합니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // renderType=component 고정 (w2calendar_holiday CSS 클래스 표시 조건)
    let properties = {
        renderType : "component"
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList([]);

    // comp 생성 함수 호출 (createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 표시월: 2025-11)
    await $c.gcm.createBasicCalendar(cList, eList);
}



// removeHoliday 호출 (선택된 케이스에 따라 분기)
// validation:
//  - removeHoliday() : setHoliday()로 설정된 휴일 모두 제거
//  - setHolidayRef()로 설정된 휴일은 제거되지 않음
//  - 'w2calendar_holiday' CSS 클래스 제거
scwin.btn_removeHoliday_onclick = function (e) {
    let caseId = con_gotoCase.getValue();
    let callLog = "";

    if (caseId === '1') {
        // 케이스 1: setHoliday('20251120') 후 removeHoliday() → setHoliday 휴일 모두 제거 (validation 1, 3)
        target1.setHoliday("20251120");
        target1.removeHoliday();
        callLog = "setHoliday('20251120') + removeHoliday()";
    } else if (caseId === '2') {
        // 케이스 2: setHolidayRef + removeHoliday + 재갱신 → Ref 휴일은 재갱신 시 복원되어 유지됨 (validation 2)
        target1.setHolidayRef("data:dlt_holidayref.label");
        target1.removeHoliday();
        target1.gotoCalendar("20251111");  // 재갱신 트리거 → holidayXpath() 재호출로 Ref 휴일 복원
        callLog = "setHolidayRef + removeHoliday + gotoCalendar('20251111') 재갱신";
    } else if (caseId === '3') {
        // 케이스 3: setHoliday + setHolidayRef + removeHoliday + 재갱신
        //          → setHolidayRef 가 우선되어 setHoliday('20251120') 은 무시
        //          → removeHoliday 후 재갱신 시 Ref 휴일만 복원됨
        target1.setHoliday("20251120");
        target1.setHolidayRef("data:dlt_holidayref.label");
        target1.removeHoliday();
        target1.gotoCalendar("20251111");  // 재갱신 트리거 → Ref 휴일 복원, setHoliday 휴일은 미복원
        callLog = "setHoliday + setHolidayRef + removeHoliday + gotoCalendar('20251111') 재갱신";
    }

    // 호출 후 휴일 셀 일자 + 첫 번째 휴일 셀의 className (w2calendar_holiday 클래스 적용 여부)
    let holidayCells = target1.render.querySelectorAll('.w2calendar_holiday');
    let holidayDays = [];
    for (var i = 0; i < holidayCells.length; i++) {
        holidayDays.push(holidayCells[i].textContent);
    }
    let firstClassName = holidayCells.length > 0 ? holidayCells[0].className : '(휴일 셀 없음)';

    wf_body_bottom.getObj("scwin").setReturnValue("[호출] " + callLog);
    wf_body_bottom.getObj("scwin").setReturnValue("[호출 후 휴일 일자] " + holidayDays.join(','));
    wf_body_bottom.getObj("scwin").setReturnValue("[첫 휴일 셀 className] " + firstClassName);
};
